const HABITS = [
  { key: "Rhizomatous",       color: "#293A2E", note: "Creeping stems at soil level; the backbone of the collection." },
  { key: "Cane",              color: "#F68A3D", note: "Tall, jointed bamboo-like stems with angel-wing leaves." },
  { key: "Shrub",             color: "#8EA937", note: "Soft-wooded, freely branching upright growers." },
  { key: "Rex",               color: "#A2568D", note: "Rhizomatous cultivars grown for spectacular foliage." },
  { key: "Tuberous",          color: "#C79C0B", note: "Dormancy-forming tubers; showy seasonal blooms." },
  { key: "Trailing-Scandent", color: "#004A4A", note: "Climbing or cascading stems for baskets & walls." },
  { key: "Thick-Stem",        color: "#8A7B5E", note: "Stout, sparsely-branched succulent-stemmed forms." },
  { key: "Semperflorens",     color: "#7A2318", note: "Wax begonias — compact, ever-blooming bedding plants." },
  { key: "Unspecified",       color: "#B3B5AA", note: "Habit not yet recorded." },
];
