function locationLabel(code) {
  if (!code) return "Unassigned";
  if (code === "CGH") return "Conservation Greenhouse";
  const m = code.match(/^CGH_?(\d+)/);
  if (m) return "Table " + parseInt(m[1], 10);
  return code;
}

function countBy(rows, fn) {
  const m = new Map();
  for (const r of rows) {
    const k = fn(r);
    if (k == null || k === "") continue;
    m.set(k, (m.get(k) || 0) + 1);
  }
  return m;
}

